use glass
select * from [dbo].[customer_shopping_behavior]
--1.Revenue Analysis-
--compared total revenue generated by male and female customer
select Gender ,sum(purchase_amount) as revenue from [dbo].[customer_shopping_behavior] group by gender

--2.Discount and spending analysis
--Identified discount user whose purchase amounts were at or above the overall average
select customer_id,purchase_amount from [dbo].[customer_shopping_behavior]
where discount_applied='yes'
and purchase_amount>=(select avg(purchase_amount) from  [dbo].[customer_shopping_behavior])

--3product rating analysis
--ranked the top 5 products by average review rating

select top 5 item_purchased,
cast(round(avg(review_rating),2) as decimal(10,2)) as "Average product rating"
from [dbo].[customer_shopping_behavior]
group by item_purchased order by avg(review_rating) desc



--4shipping analysis-
--compared average purchase amount for standard and express shipping

select shipping_type,avg(purchase_amount)
from [dbo].[customer_shopping_behavior]
where shipping_type in ('standard','Express')
group by shipping_type


--5subscription analysis-
--compared customer counts,average spending,and total revenue between subscribers
--and non-subscribers.

select subscription_status,
count(customer_id) as total_customers,
cast(round(avg(purchase_amount),2) as decimal(10,2)) as avg_spend,
cast(round(sum(purchase_amount),2) as decimal(10,2)) as total_revenue
from [dbo].[customer_shopping_behavior]
group by subscription_status
order by total_revenue,avg_spend desc


--6Discount dependency analysis-
--Identified the top 6 products by percentage of purchase with discounts applied
SELECT TOP 5
    item_purchased,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN discount_applied = 'yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*), 2
    ) AS discount_rate

FROM [dbo].[customer_shopping_behavior]

GROUP BY item_purchased

ORDER BY discount_rate DESC


--customer segmentation-
--classified customers into new,returning, and loyal segments based on previous purchase
WITH customer_type AS
(
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_category
    FROM [dbo].[customer_shopping_behavior]
)

SELECT
    customer_category,
    COUNT(*) AS Number_of_customers
FROM customer_type
GROUP BY customer_category

--8 product popularlarity analysis-
--identified the top 3 most purchased product within each category

WITH item_counts AS
(
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER
        (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM [dbo].[customer_shopping_behavior]
    GROUP BY category, item_purchased
)

SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank


--9 Repeat buyer analysis-
--compared subscription status among customers with more than 5 previous purchase
select subscription_status,
count(customer_id) as repeated_buyers
from [dbo].[customer_shopping_behavior]  where previous_purchases>5
group by subscription_status


--10 age group revenue analysis-
--compared total revenue across customer age groups
select age_group,sum(purchase_amount) as total_revenue
from [dbo].[customer_shopping_behavior]
group by age_group order by total_revenue desc

























